// ── PRISTINE NATIVE 3D EARTHOSLAB SATELLITE PROVING GROUND POINT CLOUD ──
// Auto-generated native point cloud reconstructed directly from the master satellite circuit.
// 100% matched to the WorldRing Matrix / LiDAR Phosphor Color Theme. Zero external image textures.
// Features: One seamless road turn into 'e' (zero splits/stubs), rounded dome 't', tamed vehicle lights.

const COUNT = 32201;
const POS_B64 = "";
const COL_B64 = "";
const SZ_B64 = "";
const AL_B64 = "";
const CAT_B64 = "";

function b64ToFloat32Array(b64: string): Float32Array {
  const binStr = atob(b64);
  const len = binStr.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binStr.charCodeAt(i);
  }
  return new Float32Array(bytes.buffer);
}

let cachedData: {
  positions: Float32Array;
  colors: Float32Array;
  sizes: Float32Array;
  alphas: Float32Array;
  categories: Float32Array;
  count: number;
} | null = null;

export function getEarthosCircuitPoints() {
  if (!cachedData) {
    cachedData = {
      positions: b64ToFloat32Array(POS_B64),
      colors: b64ToFloat32Array(COL_B64),
      sizes: b64ToFloat32Array(SZ_B64),
      alphas: b64ToFloat32Array(AL_B64),
      categories: b64ToFloat32Array(CAT_B64),
      count: COUNT,
    };
  }
  return cachedData;
}

// Entrance ramp world coordinates where the connecting avenue joins seamlessly
export const CIRCUIT_ENTRANCE = {
  x: 0.0,
  z: 697.50,
};
